import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Releasing and deployment","description":"","frontmatter":{},"headers":[],"relativePath":"releasing.md","filePath":"releasing.md"}'),i={name:"releasing.md"};function n(r,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="releasing-and-deployment" tabindex="-1">Releasing and deployment <a class="header-anchor" href="#releasing-and-deployment" aria-label="Permalink to &quot;Releasing and deployment&quot;">​</a></h1><p>The release model matches encrypt-rsa: generated VitePress output is committed under <code>docs/</code>, and npm publishing uses GitHub Actions OIDC with a version check.</p><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h2><p>Source pages live in <code>documentation/</code>; <code>npm run docs</code> builds the site to <code>docs/</code>. The generated output includes <code>.nojekyll</code> and <code>CNAME</code> for <code>otp.js.org</code>.</p><p>After merging the migration, set repository <strong>Settings → Pages → Deploy from a branch</strong> to <strong>master /docs</strong>. The old site uses <strong>development /docs</strong>. Keep the custom domain <code>otp.js.org</code>.</p><p>CI rebuilds the docs and requires the generated output to match the committed site. GitHub Pages deploys that directory when changes reach master. No npm release is needed for a docs-only change.</p><h2 id="configure-npm-trusted-publishing" tabindex="-1">Configure npm trusted publishing <a class="header-anchor" href="#configure-npm-trusted-publishing" aria-label="Permalink to &quot;Configure npm trusted publishing&quot;">​</a></h2><p>In the npm package settings for <code>gen-totp</code>, add a GitHub Actions trusted publisher with:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Organization or user</td><td><code>miladezzat</code></td></tr><tr><td>Repository</td><td><code>gen-totp</code></td></tr><tr><td>Workflow filename</td><td><code>publish.yml</code></td></tr><tr><td>Environment</td><td>Leave blank</td></tr></tbody></table><p>The workflow uses Node.js 24, npm 11.13.0, and <code>id-token: write</code>. It publishes without <code>NPM_TOKEN</code>. Configure the trusted publisher before merging a version bump. After confirming trusted publication, remove the obsolete token from the repository if it is no longer used elsewhere.</p><h2 id="release-a-new-version" tabindex="-1">Release a new version <a class="header-anchor" href="#release-a-new-version" aria-label="Permalink to &quot;Release a new version&quot;">​</a></h2><ol><li>Choose the version appropriate for the compatibility changes and update the changelog.</li><li>Run <code>npm run release</code> or update package metadata using your normal release process.</li><li>Run the full validation commands, rebuild the docs, and commit all changed files, including <code>package-lock.json</code>.</li><li>Merge the reviewed release into master.</li></ol><p><code>publish.yml</code> compares the stable local version with npm latest. Equal versions skip publication; lower versions fail; higher versions run lint, tests, package installation checks, and docs checks before publishing.</p><p>After a successful publish, the workflow polls the exact npm version and checks its integrity metadata. A registry timeout fails verification without publishing again. Inspect npm before retrying a release.</p><h2 id="validate-locally" tabindex="-1">Validate locally <a class="header-anchor" href="#validate-locally" aria-label="Permalink to &quot;Validate locally&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-release.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify-release.js</span></span></code></pre></div><p>These commands read npm metadata. They do not publish a package. <code>npm run test:release</code> tests the version gate and verification behavior using stubbed registry responses.</p>`,17)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
